import { writable, derived, get } from 'svelte/store';
import { _ } from 'svelte-i18n';
import { uuidv7 } from 'uuidv7';
import { Parser } from 'expr-eval';

const parser = new Parser();
// Use the global rollHistory from characterStore for now to have a unified history
// We import as type any or handle the JS import properly
// @ts-ignore
import { rollHistory, appSettings, isHistoryOpen, hasUnreadRolls, modalState } from './characterStore';

export interface SotDLSpell {
  id: string;
  name: string;
  tradition: string;
  rank: number; // 0-10
  type: string; // Attack, Utility, etc.
  target: string;
  area: string;
  duration: string;
  description: string;
  castingsUsed: number; // Track how many times cast this session
  effect?: any;
}

export type TalentOrigin = 'ancestry' | 'novice' | 'expert' | 'master';

export interface SotDLTalent {
  id: string;
  name: string;
  description: string;
  origin: TalentOrigin;
  isPassive: boolean;
  uses: number;
  maxUses: number;
  effect?: any;
}

export interface SotDLCurrency {
  gc: number;
  ss: number;
  cp: number;
  bits: number;
}

export interface SotDLEquipment {
  id: string;
  name: string;
  description: string;
  type: string;
  quantity: number;
  hands?: string;
  properties?: string;
  damage?: string; // e.g., "1d3", "1d6+1"
  damageDice?: string; // Legacy support or just alias
  range?: string;
  maxUses?: number; // Consumables
  damageMod?: number; // Integer modifier for damage

  // State
  equippedState?: 'equipped' | 'off' | 'main' | 'two' | '';
  isLoaded?: boolean;
  traits?: string;

  armorType?: string;
  defenseFixed?: number;
  defenseMod?: number;
  availability?: string;
  value?: number;
}

export interface SotDLCharacter {
  id: string;
  system: 'sofdl';
  name: string;
  level: number;
  ancestry: string;
  paths: {
    novice: string;
    expert: string;
    master: string;
  };
  imageUrl?: string;

  // Attributes
  attributes: {
    strength: number;
    agility: number;
    intellect: number;
    will: number;
  };

  // Stats
  perception: number;
  defense: number;
  health: number; // Max Health
  healingRate: number;
  size: number;
  speed: number;
  power: number;

  // Status
  damage: number;
  insanity: number;
  corruption: number;

  // Details
  description: string;
  notes: string;
  professions: string[]; // No specific list, just strings
  languages: string[];
  senses: string[];
  afflictions: string[];

  // Collections
  talents: SotDLTalent[];
  spells: SotDLSpell[];
  equipment: SotDLEquipment[];
  currency: SotDLCurrency;
  effects: any[];

  // Campaign
  campaignId: string | null;
  campaignName: string | null;
  gmName: string | null;
  campaignApproval: 'pending' | 'approved' | 'rejected' | null;

  // Combat
  combatActive: boolean;
  currentRound: number;
  initiative: boolean;
  acted: boolean;
  magicSystem: 'standard' | 'forbidden_rules' | 'uncanny_arcana';
}

