// Store Definition
export const sotdlCharacter = writable<SotDLCharacter>(JSON.parse(JSON.stringify(defaultSotDLCharacter)));

export const sotdlActiveEffects = derived(sotdlCharacter, $c => $c.effects.filter(e => e.isActive));

export const sotdlDerivedStats = derived([sotdlCharacter, sotdlActiveEffects], ([$c, $effects]) => {
  // Start with base values
  const stats: Record<string, number> = {
    strength: $c.attributes.strength,
    agility: $c.attributes.agility,
    intellect: $c.attributes.intellect,
    will: $c.attributes.will,
    perception: $c.perception,
    defense: $c.defense,
    health: $c.health,
    speed: $c.speed,
    healingRate: $c.healingRate,
    power: $c.power,
    boons: 0
  };

  // Collect all modifiers from active effects
  const allMods: { target: string; type: string; value: number | string }[] = [];
  $effects.forEach(eff => {
    if (!eff.modifiers) return;
    eff.modifiers.forEach((mod: any) => {
      allMods.push(mod);
    });
  });

  // Helper to get normalized target key
  const normalizeTarget = (target: string): string => {
    if (target === 'healing_rate') return 'healingRate';
    return target;
  };

  // Apply modifiers in order: SET -> ADD -> MULT
  const statKeys = Object.keys(stats);

  statKeys.forEach(key => {
    const targetMods = allMods.filter(m => normalizeTarget(m.target) === key);
    if (targetMods.length === 0) return;

    // 1. Apply SET (last one wins, completely replaces the value)
    const setMods = targetMods.filter(m => m.type === 'SET');
    if (setMods.length > 0) {
      const lastSet = setMods[setMods.length - 1];
      stats[key] = evaluateModifierValueSotDL(lastSet.value, $c);
    }

    // 2. Apply ADDs (only if no SET, or after SET)
    // When SET exists, ADDs are ignored (SET completely overrides)
    if (setMods.length === 0) {
      const addMods = targetMods.filter(m => m.type === 'ADD');
      addMods.forEach(m => {
        stats[key] += evaluateModifierValueSotDL(m.value, $c);
      });
    }

    // 3. Apply MULTs
    const multMods = targetMods.filter(m => m.type === 'MULT');
    multMods.forEach(m => {
      stats[key] *= evaluateModifierValueSotDL(m.value, $c);
    });

    // Floor the final value
    stats[key] = Math.floor(stats[key]);
  });

  return {
    strength: stats.strength,
    agility: stats.agility,
    intellect: stats.intellect,
    will: stats.will,
    perception: stats.perception,
    defense: stats.defense,
    health: stats.health,
    speed: stats.speed,
    healingRate: stats.healingRate,
    power: stats.power,
    boons: stats.boons
  };
});

export const sotdlAttributes = derived(sotdlDerivedStats, $s => ({
  strength: $s.strength,
  agility: $s.agility,
  intellect: $s.intellect,
  will: $s.will
}));

export const sotdlModifiers = derived(sotdlDerivedStats, $s => ({
  strength: $s.strength - 10,
  agility: $s.agility - 10,
  intellect: $s.intellect - 10,
  will: $s.will - 10
}));

export const sotdlCurrentHealth = derived([sotdlCharacter, sotdlDerivedStats], ([$c, $s]) => $s.health - $c.damage);
export const sotdlIsInjured = derived([sotdlCharacter, sotdlDerivedStats], ([$c, $s]) => $c.damage >= $s.health / 2);
export const sotdlIsIncapacitated = derived([sotdlCharacter, sotdlDerivedStats], ([$c, $s]) => $c.damage >= $s.health);

export function evaluateModifierValueSotDL(value: number | string, characterObj: SotDLCharacter): number {
  if (typeof value === 'number') return value;
  if (!value) return 0;
  const sValue = String(value).trim();
  if (!isNaN(Number(sValue))) return Number(sValue);

  try {
    const context: any = {};
    if (characterObj.attributes) {
      Object.entries(characterObj.attributes).forEach(([key, val]) => {
        context[key] = val;
      });
    }
    context['level'] = characterObj.level || 0;
    context['perception'] = characterObj.perception || 0;
    context['defense'] = characterObj.defense || 0;
    context['health'] = characterObj.health || 0;
    context['healingRate'] = characterObj.healingRate || 0;
    context['size'] = characterObj.size || 0;
    context['speed'] = characterObj.speed || 0;
    context['power'] = characterObj.power || 0;
    context['damage'] = characterObj.damage || 0;
    context['insanity'] = characterObj.insanity || 0;
    context['corruption'] = characterObj.corruption || 0;

    const expression = sValue.replace(/@(\w+)/g, '$1');
    return parser.evaluate(expression, context);
  } catch (e) {
    return 0;
  }
}

export const sotdlTotalHealingRate = derived(sotdlDerivedStats, $s => Math.max(0, $s.healingRate));

export const sotdlCharacterActions = {
  set: (data: Partial<SotDLCharacter>) => {
    sotdlCharacter.update(c => {
      const newState = { ...c, ...data };
      // If health changed, update base healing rate automatically if not explicitly provided
      if (data.health !== undefined && data.healingRate === undefined) {
        newState.healingRate = Math.floor(newState.health / 4);
      }
      return newState;
    });
  },
  updateAttribute: (attr: keyof SotDLCharacter['attributes'], value: number) => {
    sotdlCharacter.update(c => ({
      ...c,
      attributes: { ...c.attributes, [attr]: value }
    }));
  },
  takeDamage: (amount: number) => {
    sotdlCharacter.update(c => {
      const newDamage = Math.max(0, Math.min(c.health, c.damage + amount));
      return { ...c, damage: newDamage };
    });
  },
  heal: (amount: number) => {
    sotdlCharacter.update(c => {
      const newDamage = Math.max(0, c.damage - amount);
      return { ...c, damage: newDamage };
    });
  },
  updateStat: (stat: 'insanity' | 'corruption', value: number) => {
    sotdlCharacter.update(c => ({ ...c, [stat]: Math.max(0, value) }));
  },
  // Effects Actions
  toggleEffect: (id: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      effects: c.effects.map(e => e.id === id ? { ...e, isActive: !e.isActive } : e)
    }));
  },
  deleteEffect: (id: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      effects: c.effects.filter(e => e.id !== id)
    }));
  },
  cleanInactiveEffects: () => {
    sotdlCharacter.update(c => ({
      ...c,
      effects: c.effects.filter(e => e.isActive)
    }));
  },
  advanceRound: (direction: 'next' | 'prev') => {
    sotdlCharacter.update(c => {
      if (direction === 'next') {
        // Auto-deactivate END_OF_ROUND effects
        const newEffects = c.effects.map(e =>
          e.isActive && e.duration === 'END_OF_ROUND'
            ? { ...e, isActive: false }
            : e
        );
        return { ...c, currentRound: c.currentRound + 1, effects: newEffects };
      }
      return { ...c, currentRound: Math.max(1, c.currentRound - 1) };
    });
  },
  checkLuckEnds: (id: string) => {
    const char = get(sotdlCharacter);
    const effect = char.effects.find(e => e.id === id);
    const t = get(_);
    modalState.set({
      type: 'pre_roll',
      isOpen: true,
      data: {
        type: 'luck_ends',
        system: 'sofdl',
        effectId: id,
        source: { name: effect?.name || t('sofdl.rolls.effect') }
      }
    });
  },
  checkConcentration: (effectId: string) => {
    const char = get(sotdlCharacter);
    const effect = char.effects.find(e => e.id === effectId);
    const t = get(_);
    modalState.set({
      type: 'pre_roll',
      isOpen: true,
      data: {
        type: 'concentration',
        system: 'sofdl',
        effectId,
        key: 'will',
        source: { name: effect?.name || t('sofdl.rolls.concentration') }
      }
    });
  },
  // Spell Actions
  addSpell: (spell: SotDLSpell) => {
    sotdlCharacter.update(c => ({
      ...c,
      spells: [...c.spells, { ...spell, id: spell.id || uuidv7() }]
    }));
  },
  updateSpell: (spell: SotDLSpell) => {
    sotdlCharacter.update(c => ({
      ...c,
      spells: c.spells.map(s => s.id === spell.id ? spell : s)
    }));
  },
  deleteSpell: (id: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      spells: c.spells.filter(s => s.id !== id)
    }));
  },
  castSpell: (id: string) => {
    const char = get(sotdlCharacter);
    const spell = char.spells.find(s => s.id === id);
    if (!spell) return;

    sotdlCharacter.update(c => ({
      ...c,
      spells: c.spells.map(s => s.id === id ? { ...s, castingsUsed: (s.castingsUsed || 0) + 1 } : s)
    }));

    sotdlCharacterActions.addToHistory({
      source: 'spell',
      name: spell.name,
      description: spell.description,
      type: 'spell'
    });
  },
  resetSpellCastings: () => {
    sotdlCharacter.update(c => ({
      ...c,
      spells: c.spells.map(s => ({ ...s, castingsUsed: 0 }))
    }));
  },
  // Talent Actions
  addTalent: (talent: SotDLTalent) => {
    sotdlCharacter.update(c => ({
      ...c,
      talents: [...c.talents, { ...talent, id: talent.id || uuidv7() }]
    }));
  },
  updateTalent: (talent: SotDLTalent) => {
    sotdlCharacter.update(c => ({
      ...c,
      talents: c.talents.map(t => t.id === talent.id ? talent : t)
    }));
  },
  deleteTalent: (id: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      talents: c.talents.filter(t => t.id !== id)
    }));
  },
  useTalent: (id: string) => {
    const char = get(sotdlCharacter);
    const talent = char.talents.find(t => t.id === id);
    if (!talent) return;

    sotdlCharacter.update(c => ({
      ...c,
      talents: c.talents.map(t => t.id === id && t.uses > 0 ? { ...t, uses: t.uses - 1 } : t)
    }));

    sotdlCharacterActions.addToHistory({
      source: 'talent',
      name: talent.name,
      description: talent.description,
      type: 'talent'
    });
  },
  resetTalentUses: () => {
    sotdlCharacter.update(c => ({
      ...c,
      talents: c.talents.map(t => ({ ...t, uses: t.maxUses }))
    }));
  },
  // Senses Actions
  addSense: (sense: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      senses: !c.senses.includes(sense) ? [...c.senses, sense] : c.senses
    }));
  },
  removeSense: (index: number) => {
    sotdlCharacter.update(c => ({
      ...c,
      senses: c.senses.filter((_, i) => i !== index)
    }));
  },
  // Afflictions Actions
  toggleAffliction: (aff: string) => {
    sotdlCharacter.update(c => ({
      ...c,
      afflictions: c.afflictions.includes(aff)
        ? c.afflictions.filter(a => a !== aff)
        : [...c.afflictions, aff]
    }));
  },
  leaveCampaign: () => {
    sotdlCharacter.update(c => ({
      ...c,
      campaignId: null,
      campaignName: null,
      gmName: null,
      campaignApproval: null
    }));
  },
  // History Actions
  addToHistory: (rollData: any, shouldSync = true) => {
    const char = get(sotdlCharacter);
    // Use the global rollHistory from characterStore for now to have a unified history

    const entry = {
      id: rollData.id || uuidv7(),
      timestamp: rollData.timestamp || new Date(),
      charName: char.name,
      ...rollData
    };

    rollHistory.update((h: any[]) => [entry, ...h]);

    const settings = get(appSettings);
    if (settings.autoOpenHistory) {
      isHistoryOpen.set(true);
    } else if (!get(isHistoryOpen)) {
      hasUnreadRolls.set(true);
    }

    // Sync via Trystero if in a campaign
    if (shouldSync && char.campaignId) {
      import('$lib/logic/sync').then(({ syncRoll }) => {
        syncRoll(entry);
      });
    }
  },
  // Languages & Professions
  addLanguage: (lang: string) => sotdlCharacter.update(c => ({ ...c, languages: [...c.languages, lang] })),
  removeLanguage: (index: number) => sotdlCharacter.update(c => ({ ...c, languages: c.languages.filter((_, i) => i !== index) })),
  addProfession: (prof: string) => sotdlCharacter.update(c => ({ ...c, professions: [...c.professions, prof] })),
  removeProfession: (index: number) => sotdlCharacter.update(c => ({ ...c, professions: c.professions.filter((_, i) => i !== index) })),

  // Currency Actions
  updateCurrency: (type: 'gc' | 'ss' | 'cp' | 'bits', amount: number) => {
    sotdlCharacter.update(c => {
      const newVal = Math.max(0, (c.currency[type] || 0) + amount);
      return { ...c, currency: { ...c.currency, [type]: newVal } };
    });
  },

  // Inventory / Equipment Actions
  addItem: (item: SotDLEquipment) => sotdlCharacter.update(c => ({ ...c, equipment: [...c.equipment, item] })),
  updateItem: (item: SotDLEquipment) => sotdlCharacter.update(c => ({
    ...c,
    equipment: c.equipment.map(i => i.id === item.id ? item : i)
  })),
  deleteItem: (itemId: string) => sotdlCharacter.update(c => ({
    ...c,
    equipment: c.equipment.filter(i => i.id !== itemId)
  })),

  useConsumable: (item: SotDLEquipment) => {
    sotdlCharacter.update(c => ({
      ...c,
      equipment: c.equipment.map(i => i.id === item.id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i)
    }));
    // Optional: Add to history that item was used
  },

  reloadWeapon: (item: SotDLEquipment) => sotdlCharacter.update(c => ({
    ...c,
    equipment: c.equipment.map(i => i.id === item.id ? { ...i, isLoaded: true } : i)
  })),

  // Roll Logic
  finalizeRoll: (data: any, modifier: number, selectedEffects: string[] = [], options: { suppressHistory?: boolean } = {}) => {
    const char = get(sotdlCharacter);
    const mods = get(sotdlModifiers);
    const derivedStats = get(sotdlDerivedStats);

    const isDamage = data?.type === 'weapon_damage' || data?.type === 'spell_damage';
    const t = get(_);
    const sourceName = data?.source?.name || data?.key || t('character.modals.attribute');

    let resultData: any = {};
    let commitFn = () => { };

    if (!isDamage) {
      const d20 = Math.floor(Math.random() * 20) + 1;
      let attrMod = 0;
      let attrLabel = sourceName;

      if (data.type === 'attribute') {
        attrMod = mods[data.key as keyof typeof mods] || 0;
        attrLabel = t(`sofdl.attributes.${data.key}`);
      } else if (data.type === 'luck') {
        attrMod = 0;
        attrLabel = t('character.luck_test');
      }

      // Boon/Bane Logic (1d6 highest)
      let netModifier = modifier + (derivedStats.boons || 0);
      let boonBaneTotal = 0;
      let boonBaneStr = '';
      let boonBaneRolls: number[] = [];

      if (netModifier !== 0) {
        const numDice = Math.abs(netModifier);
        for (let i = 0; i < numDice; i++) boonBaneRolls.push(Math.floor(Math.random() * 6) + 1);
        const highest = Math.max(...boonBaneRolls);

        if (netModifier > 0) {
          boonBaneTotal = highest;
          boonBaneStr = ` + ${highest} [${t('sofdl.rolls.boon')}]`;
        } else {
          boonBaneTotal = -highest;
          boonBaneStr = ` - ${highest} [${t('sofdl.rolls.bane')}]`;
        }
      }

      let source = 'attribute';
      if (data.type === 'weapon_attack') source = 'attack';
      else if (data.type === 'luck' || data.type === 'luck_ends') source = 'luck';

      const total = d20 + attrMod + boonBaneTotal;
      const formula = `d20(${d20})${attrMod !== 0 ? (attrMod >= 0 ? '+' : '') + attrMod : ''}${boonBaneStr}`;

      resultData = { d20, boonBaneDice: boonBaneRolls, total, formula };

      commitFn = () => {
        sotdlCharacterActions.addToHistory({
          source,
          name: attrLabel,
          description: data.type === 'luck_ends'
            ? t('sofdl.rolls.luck_ends', { values: { effect: sourceName } })
            : t('sofdl.rolls.attribute_test', { values: { attr: attrLabel, modifier } }),
          formula,
          total: total,
          crit: d20 === 20,
          effectsApplied: selectedEffects
        });

        // Special logic for luck_ends
        if (data.type === 'luck_ends' && total >= 10) {
          sotdlCharacter.update(c => ({
            ...c,
            effects: c.effects.map(e => e.id === data.effectId ? { ...e, isActive: false } : e)
          }));
        }
      };

    } else {
      // Damage roll for SotDL
      const rawDamage = data.source?.damage ?? data.source?.damageDice ?? '1d6';
      const damageStr = String(rawDamage);
      const damageMod = Number(data.source?.damageMod) || 0;

      let sum = 0;
      let results: number[] = [];
      let formula = '';

      if (damageStr === '0') {
        sum = 0;
        formula = '0';
      } else if (!damageStr.includes('d')) {
        sum = parseInt(damageStr) || 0;
        formula = `${sum}`;
        results = [sum];
      } else {
        const match = damageStr.match(/(\d+)d(\d+)/);
        if (match) {
          const count = parseInt(match[1]) || 1;
          const sides = parseInt(match[2]) || 6;
          for (let i = 0; i < count; i++) {
            const r = Math.floor(Math.random() * sides) + 1;
            sum += r;
            results.push(r);
          }
          formula = `${damageStr} [${results.join(', ')}]`;
        } else {
          sum = 1;
          formula = '1';
        }
      }

      const total = sum + modifier + damageMod;
      const modStr = (modifier + damageMod) !== 0 ? `${(modifier + damageMod) > 0 ? '+' : ''}${modifier + damageMod}` : '';
      const finalFormula = `${formula}${modStr}`;

      resultData = { damageDice: results, total, formula: finalFormula };

      commitFn = () => {
        const t = get(_);
        sotdlCharacterActions.addToHistory({
          source: 'damage',
          name: sourceName,
          description: t('sofdl.rolls.damage_description', { values: { source: sourceName } }),
          formula: finalFormula,
          total: total,
          effectsApplied: selectedEffects
        });
      };
    }

    if (!options.suppressHistory) {
      commitFn();
    }

    return { ...resultData, commit: commitFn };
  },
  // Rest action
  rest: () => {
    sotdlCharacter.update(c => {
      // Reset all spell castings
      const resetSpells = c.spells.map(s => ({ ...s, castingsUsed: 0 }));

      // Reset all talent uses
      const resetTalents = c.talents.map(t => ({
        ...t,
        uses: t.isPassive ? 0 : t.maxUses
      }));

      // Heal damage equal to healing rate
      const newDamage = Math.max(0, c.damage - c.healingRate);

      return {
        ...c,
        spells: resetSpells,
        talents: resetTalents,
        damage: newDamage
      };
    });
  }
};
